function decorateLambdaPanelHelp(section, root = document) {
  for (const [selector, title, helpKey] of lambdaPanelHelpTargets[section] ?? []) {
    const heading = root.querySelector(`${selector} > .card-header h2`);
    if (!heading || heading.textContent.trim() !== title && !heading.textContent.trim().startsWith(`${title} (`)) continue;
    const meta = heading.querySelector(".muted")?.textContent.trim() ?? "";
    heading.outerHTML = panelHeading(title, lambdaPanelHelp[helpKey], meta);
  }
}

function bytesBase64(bytes) {
  let binary = "";
  for (let index = 0; index < bytes.length; index += 32768) binary += String.fromCharCode(...bytes.subarray(index, index + 32768));
  return btoa(binary);
}

function crc32(bytes) {
  let crc = 0xffffffff;
  for (const byte of bytes) {
    crc ^= byte;
    for (let bit = 0; bit < 8; bit++) crc = (crc >>> 1) ^ (crc & 1 ? 0xedb88320 : 0);
  }
  return (crc ^ 0xffffffff) >>> 0;
}

function inlineLambdaZipBase64(source) {
  const encoder = new TextEncoder(); const name = encoder.encode("index.mjs"); const content = encoder.encode(source); const checksum = crc32(content);
  const localSize = 30 + name.length + content.length; const centralSize = 46 + name.length; const bytes = new Uint8Array(localSize + centralSize + 22); const view = new DataView(bytes.buffer);
  view.setUint32(0, 0x04034b50, true); view.setUint16(4, 20, true); view.setUint32(14, checksum, true); view.setUint32(18, content.length, true); view.setUint32(22, content.length, true); view.setUint16(26, name.length, true); bytes.set(name, 30); bytes.set(content, 30 + name.length);
  const central = localSize; view.setUint32(central, 0x02014b50, true); view.setUint16(central + 4, 0x031e, true); view.setUint16(central + 6, 20, true); view.setUint32(central + 16, checksum, true); view.setUint32(central + 20, content.length, true); view.setUint32(central + 24, content.length, true); view.setUint16(central + 28, name.length, true); view.setUint32(central + 38, (0o100644 << 16) >>> 0, true); bytes.set(name, central + 46);
  const end = localSize + centralSize; view.setUint32(end, 0x06054b50, true); view.setUint16(end + 8, 1, true); view.setUint16(end + 10, 1, true); view.setUint32(end + 12, centralSize, true); view.setUint32(end + 16, localSize, true);
  return bytesBase64(bytes);
}

function validateInlineLambdaSource(source, handler) {
  const match = /^index\.([A-Za-z_$][\w$]*)$/.exec(handler);
  if (!source.trim()) throw new Error("Enter JavaScript code for the function");
  if (!match) throw new Error("Inline code uses index.mjs, so the handler must start with index.");
  const exportName = match[1].replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const exported = new RegExp(`export\\s+(?:(?:async\\s+)?function\\s+${exportName}\\b|(?:const|let|var)\\s+${exportName}\\b)|export\\s*\\{[^}]*\\b${exportName}\\b`).test(source);
  if (!exported) throw new Error(`Inline code must export ${match[1]} to match the ${handler} handler`);
}

function lambdaLogGroupName(fn = {}) { return fn.LoggingConfig?.LogGroup || `/aws/lambda/${fn.FunctionName}`; }
function lambdaLogGroupHref(fn = {}) { return `#/cloudwatch/log-groups/${encodeURIComponent(lambdaLogGroupName(fn))}`; }

