    main.innerHTML = `<div class="page-width">${pageHeader("Capacity providers", "Manage the compute constraints used by Lambda Managed Instances functions.", '<button class="button refresh" data-action="refresh" title="Refresh">↻</button><button class="button primary" data-action="create-capacity-provider">Create capacity provider</button>')}<div class="alert warning"><strong>Local control-plane model</strong><br>Provider lifecycle, validation, assignment, tags, and function scaling are durable. No EC2, ENI, EBS, VPC, KMS, or telemetry infrastructure is fabricated.</div><section class="card capacity-providers-card"><div class="card-header"><h2>Capacity providers <span class="muted">(${providers.length})</span></h2></div><div class="toolbar"><label class="filter"><span>⌕</span><input data-filter-table placeholder="Find capacity providers"></label></div><div class="table-wrap">${providers.length ? `<table><thead><tr><th>Name</th><th>State</th><th>Architecture</th><th>Scaling</th><th>VPC</th><th>Last modified</th></tr></thead><tbody>${providers.map(item => { const name = providerName(item); return `<tr data-search-row="${escapeHtml(`${name} ${item.State} ${item.CapacityProviderArn}`.toLowerCase())}"><td><a href="#/lambda/capacity-providers/${encodeURIComponent(name)}">${escapeHtml(name)}</a><div class="muted small mono">${escapeHtml(item.CapacityProviderArn)}</div></td><td><span class="status ${providerStateClass(item.State)}">${escapeHtml(item.State)}</span></td><td>${escapeHtml(item.InstanceRequirements?.Architectures?.[0] || "Not constrained")}</td><td>${escapeHtml(item.CapacityProviderScalingConfig?.ScalingMode || "Not configured")} · ${item.CapacityProviderScalingConfig?.MaxVCpuCount ?? "–"} vCPUs</td><td>${item.VpcConfig?.SubnetIds?.length ?? 0} subnet(s) · ${item.VpcConfig?.SecurityGroupIds?.length ?? 0} group(s)</td><td>${formatDate(item.LastModified)}</td></tr>`; }).join("")}</tbody></table>` : emptyState("▦", "No capacity providers", "Create a control-plane provider before assigning a Lambda Managed Instances function.", '<button class="button primary" data-action="create-capacity-provider">Create capacity provider</button>')}</div></section></div>`;
