    main.innerHTML = `<div class="page-width">${pageHeader(name, `arn:aws:lambda:${ui.summary?.region}:${ui.summary?.accountId}:layer:${name}`, `<a class="button primary" href="#/lambda/layers/${encodeURIComponent(name)}/create">Publish new version</a>`)}<section class="card layer-versions-card"><div class="card-header"><div><h2>Versions <span class="muted">(${versions.length})</span></h2><p class="muted small">Versions are immutable and listed newest first.</p></div></div><div class="table-wrap">${versions.length ? `<table><thead><tr><th>Version</th><th>Description</th><th>Compatible runtimes</th><th>Architectures</th><th>Created</th><th>Actions</th></tr></thead><tbody>${versions.map(version => `<tr><td><a href="#/lambda/layers/${encodeURIComponent(name)}/versions/${version.Version}"><strong>${version.Version}</strong></a></td><td>${escapeHtml(version.Description || "–")}</td><td>${escapeHtml(version.CompatibleRuntimes?.join(", ") || "All")}</td><td>${escapeHtml(version.CompatibleArchitectures?.join(", ") || "All")}</td><td>${formatDate(version.CreatedDate)}</td><td><button class="button" data-copy="${escapeHtml(version.LayerVersionArn)}">Copy ARN</button> <button class="button danger" data-delete-layer-version="${version.Version}">Delete</button></td></tr>`).join("")}</tbody></table>` : emptyState("▱", "No active versions", "Deleted versions remain usable by functions that already reference them, but cannot be attached again.", `<a class="button primary" href="#/lambda/layers/${encodeURIComponent(name)}/create">Publish new version</a>`)}</div></section></div>`;
