  async function s3LambdaTriggerInventory(functionArn) {
    const listed = await s3Request("/?max-buckets=100"); const buckets = [...listed.xml.getElementsByTagName("Bucket")].map(node => node.getElementsByTagName("Name")[0]?.textContent).filter(Boolean);
    const results = []; const unavailableBuckets = [];
    for (const bucket of buckets) {
      let notification;
      try { notification = await s3Request(`/${encodeURIComponent(bucket)}?notification`); }
      catch (error) {
        if (error?.status !== 403 && error?.status !== 404) throw error;
        unavailableBuckets.push(bucket); continue;
      }
      for (const config of notification.xml.getElementsByTagName("LambdaFunctionConfiguration")) {
        const value = name => config.getElementsByTagName(name)[0]?.textContent ?? "";
        const ruleValue = (node, name) => node?.getElementsByTagName(name)[0]?.textContent ?? "";
        const arn = value("LambdaFunctionArn"); if (arn !== functionArn && !arn.startsWith(`${functionArn}:`)) continue;
        const rules = [...config.getElementsByTagName("FilterRule")];
        results.push({ bucket, id: value("Id"), arn, events: [...config.getElementsByTagName("Event")].map(node => node.textContent), prefix: ruleValue(rules.find(node => ruleValue(node, "Name") === "prefix"), "Value"), suffix: ruleValue(rules.find(node => ruleValue(node, "Name") === "suffix"), "Value") });
      }
    }
    return { triggers: results, unavailableBuckets };
  }

