    const deliveryGuidance = mappings.some(mapping => isSqsEventSourceArn(mapping.EventSourceArn)) ? "<strong>At-least-once event delivery</strong><br>DynamoDB checkpoints and SQS acknowledgement state advance only after successful handling. Source-specific filters, retries, partial batch responses, and concurrency controls are durable across restart." : "<strong>At-least-once stream delivery</strong><br>Checkpoints advance after successful handling. Filters, partial batch responses, retries, age limits, and bisection are durable across restart.";
    const triggers = `<section class="card trigger-card"><div class="card-header"><div><h2>Triggers <span class="muted">(${mappings.length})</span></h2><p class="muted small">Event sources that invoke this function.</p></div><button class="button primary" data-action="add-trigger">Add trigger</button></div><div class="table-wrap">${mappings.length ? `<table><thead><tr><th>Source</th><th>State</th><th>Batch</th><th>Configuration</th><th>Last processing result</th><th>Actions</th></tr></thead><tbody>${rows}</tbody></table>` : emptyState("↯", "No triggers", "Add a DynamoDB stream or SQS queue trigger to invoke this function.", '<button class="button primary" data-action="add-trigger">Add trigger</button>')}</div><div class="card-body"><div class="alert info">${deliveryGuidance}</div></div></section>`;
