    const s3TriggerCard = `<section class="card s3-trigger-inventory"><div class="card-header"><div><h2>S3 bucket notifications <span class="muted">(${s3Triggers.length})</span></h2><p class="muted small">Bucket notification configurations that invoke this function asynchronously.</p></div></div>${inventoryWarning}<div class="table-wrap">${s3Triggers.length ? `<table><thead><tr><th>Bucket</th><th>Configuration</th><th>Events</th><th>Key filter</th><th>Target</th></tr></thead><tbody>${s3Triggers.map(trigger => `<tr><td><a href="#/s3/buckets/${encodeURIComponent(trigger.bucket)}/properties">${escapeHtml(trigger.bucket)}</a></td><td>${escapeHtml(trigger.id)}</td><td>${escapeHtml(trigger.events.join(", "))}</td><td class="mono">${escapeHtml(`${trigger.prefix || "*"} … ${trigger.suffix || "*"}`)}</td><td class="mono">${escapeHtml(trigger.arn)}</td></tr>`).join("")}</tbody></table>` : '<div class="card-body"><p class="muted">No visible S3 notification configuration targets this function. Configure the bucket from S3 Properties after granting its resource-based invoke permission.</p></div>'}</div></section>`;
