    document.querySelectorAll("[data-toggle-trigger]").forEach(button => button.addEventListener("click", async () => { await rest(`/2015-03-31/event-source-mappings/${encodeURIComponent(button.dataset.toggleTrigger)}`, "PUT", { Enabled: button.dataset.enabled !== "true" }); toast(`Trigger ${button.dataset.enabled === "true" ? "disabled" : "enabled"}`); await route(); }));
