    const layerCard = image ? "" : `<div class="card layers-card"><div class="card-header"><div><h2>Layers <span class="muted">(${attachedLayers.length}/5)</span></h2><p class="muted small">Layers are merged under /opt in this order. Later layers overwrite earlier files.</p></div><button class="button" data-action="add-layer" ${attachedLayers.length >= 5 ? "disabled" : ""}>Add a layer</button></div><div class="table-wrap">${layerRows ? `<table><thead><tr><th>Order</th><th>Layer version ARN</th><th>Code size</th><th>Actions</th></tr></thead><tbody>${layerRows}</tbody></table>` : emptyState("▱", "No layers", "Attach a compatible layer version to share dependencies and runtime files.")}</div></div>`;
    const functionUrlRows = (functionUrls ?? []).map(config => { const qualifier = config.FunctionArn === fn.FunctionArn ? "$LATEST" : config.FunctionArn.split(":").at(-1); const cors = config.Cors ? `${config.Cors.AllowOrigins?.join(", ") || "No origins"} · ${config.Cors.AllowMethods?.join(", ") || "No methods"}` : "Not configured"; return `<tr><td><strong>${escapeHtml(qualifier)}</strong><div class="muted small">${formatDate(config.CreationTime)}</div></td><td><a class="mono function-url-link" href="${escapeHtml(config.FunctionUrl)}" target="_blank" rel="noreferrer">${escapeHtml(config.FunctionUrl)}</a></td><td><span class="status ${config.AuthType === "NONE" ? "pending" : ""}">${escapeHtml(config.AuthType)}</span></td><td>${escapeHtml(config.InvokeMode)}</td><td>${escapeHtml(cors)}</td><td><button class="button" data-copy="${escapeHtml(config.FunctionUrl)}">Copy</button> <a class="button" href="${escapeHtml(config.FunctionUrl)}" target="_blank" rel="noreferrer">Open</a> <button class="button" data-edit-function-url="${escapeHtml(qualifier)}">Edit</button> <button class="button danger" data-delete-function-url="${escapeHtml(qualifier)}">Delete</button></td></tr>`; }).join("");
