    const runtimeCard = image ? `<div class="card runtime-settings-card"><div class="card-header"><div><h2>Runtime settings</h2><p class="muted small">Image platform and writable scratch configuration.</p></div><button class="button" data-action="edit-runtime-settings">Edit</button></div><div class="card-body detail-grid"><dl class="key-value"><dt>Runtime</dt><dd>Container image</dd><dt>Architecture</dt><dd>${escapeHtml(fn.Architectures?.[0] || "x86_64")}</dd></dl><dl class="key-value"><dt>Ephemeral storage</dt><dd>${fn.EphemeralStorage?.Size ?? 512} MB</dd><dt>Root filesystem</dt><dd>Read-only when executed</dd></dl></div><div class="card-body"><div class="alert warning"><strong>Local executor required</strong><br>Metadata and architecture are validated at deployment. OCI-only sources remain dependency-blocked at invocation; no image root filesystem is host-executed.</div></div></div>` : `<div class="card runtime-settings-card"><div class="card-header"><div><h2>Runtime settings</h2><p class="muted small">Execution architecture, scratch space, and runtime update reference.</p></div><button class="button" data-action="edit-runtime-settings">Edit</button></div><div class="card-body detail-grid"><dl class="key-value"><dt>Runtime</dt><dd>${escapeHtml(fn.Runtime)}</dd><dt>Architecture</dt><dd>${escapeHtml(fn.Architectures?.[0] || "x86_64")}</dd><dt>Ephemeral storage</dt><dd>${fn.EphemeralStorage?.Size ?? 512} MB</dd></dl><dl class="key-value"><dt>Update mode</dt><dd>${escapeHtml(runtimeManagement?.UpdateRuntimeOn || "Auto")}</dd><dt>Runtime version ARN</dt><dd class="mono">${escapeHtml(runtimeManagement?.RuntimeVersionArn || "Host-managed")}</dd><dt>Handler</dt><dd class="mono">${escapeHtml(fn.Handler)}</dd></dl></div><div class="card-body"><div class="alert info"><strong>Local runtime behavior</strong><br>Architecture is enforced for native artifacts. Each invocation gets an isolated scratch directory and the configured size is exposed to the runtime; the host filesystem does not impose a byte quota. Runtime version ARNs round-trip as references while the local Node.js binary remains host-managed.</div></div></div>`;
